  if (fromEnv) return fromEnv
  try {
    // Windows user env may postdate the running dsh process; read the registry.
    const { stdout } = await execFileAsync(
      'reg',
      ['query', 'HKCU\\Environment', '/v', 'GLM_API_KEY'],
